const scan=read(R+'step8-liveness.json'),ac=read(R+'step8-carriage-accounting.json'),registry=read(R+'working-identity-registry.json'),identity=gen.buildIdentityRegistryIndex(registry),sb=gen.buildSwitchboardIndex(read(P+'transitional-switchboard.json')),vocabulary=read(P+'claim-and-disposition-vocabulary.json');
