const restoreLinks=t=>{for(const f of ac.files)for(const r of f.relativeLinkRebases||[])t=t.replaceAll(']('+r.to+')',']('+r.from+')');return t;};
const allTargets=[...new Set([...ac.candidateFiles.map(f=>f.path),'docs/platform/herdr-web-dashboard/operations/operator-runbook.md','docs/platform/herdr-web-dashboard/contracts/fgos-gateway-api-v1.yaml'])];
