const reverse=conservation.unreferencedCandidateRows.map(r=>{const item=items.find(i=>i.path===r.path);return {path:r.path,anchor:r.anchor,unitDigest:r.unitDigest,fileStatus:'Candidate',canonical:false,identityState:claims.find(c=>c.claimId===r.claimId)?.identityStatus,provisionalLocalIdentity:true};});
const duplicateGroups=[];for(const digest of new Set(sourceOnly.claimLedger.map(r=>r.sourceUnitDigest))){const members=sourceOnly.claimLedger.filter(r=>r.sourceUnitDigest===digest&&r.targetOwner);if(new Set(members.map(r=>r.targetOwner)).size>1)duplicateGroups.push({digest,members:members.map(r=>({claimId:r.claimId,sourcePath:r.sourcePath,sourceAnchor:r.sourceAnchor,targetOwner:r.targetOwner,targetAnchor:r.targetAnchor})),status:'pending independent contextual exception review',rationale:'Shared heading-only Behaviors & Operations has different area subjects and different child operations. Preserve contextual owners per the frozen area map; do not treat the plugin behavior section as citation-check behavior or the converse.'});}
const stats={sourceRows:566,withCarrier:digestChecks.length,noCandidateGenerated:9,candidates:ac.candidateFiles.length,scopes:scopes.length,allScopesMatched:true,allSourceNativeIdentitiesPresent:true,allSourceTextAndTargetBindingsChecked:true,originalHeadingPayloadContainedAfterRecordedLinkReversal:true,frontmatterChecks:[],machineByteChecks:[],segmentReconstructionChecks:[]};
