 const ls=source.split('\n');assert.equal(f.segments.map(s=>ls.slice(s.startLine-1,s.endLine).join('\n')).join('\n'),source);for(const seg of f.segments){const body=ls.slice(seg.startLine-1,seg.endLine).join('\n');assert.equal(sha(body),seg.sha256);if(!f.source.endsWith('.md'))continue;const candidate=restoreLinks(fs.readFileSync(seg.target,'utf8'));if(seg.startLine===1&&candidate.includes('```txt\nDocument type:')){const restored=candidate.replace(/\n\n```txt\nDocument type:[\s\S]*?\n```\n\n> Added in candidate:[^\n]*\n/,'');assert(restored.includes(body.trim()),'first segment restore '+f.source);}else assert(candidate.includes(body.trim()),'segment missing '+f.source);}stats.segmentReconstructionChecks.push(f.source);
}
const result={version:1,method:'Scoped D/E FAST CHECK ONLY: unchanged applyDecisions, vocabulary validator and checkConservation on working-tree source/candidate overlay; 27 repeated --scope equivalents, both prior registry row-set checks. No native sync, git tree writes, checkInventory committed-tree scan, persisted registry mutation or review pack. Source IDs are actual current native IDs; new candidate local gap IDs are diagnostic and omitted from this report. Full D/E/native identity and reverse-list equality must run once after runner commits.',sourceCommit:scan.sourceCommit,followupCommit:'b4d758676561e36d320792cacd7128645a90bd43',linkRebaseProof:'Only source-payload containment assertions reverse recorded Markdown destinations; gate inputs, actual target digests and unchanged exported D/E rules use actual candidate bytes.',registry:{path:R+'working-identity-registry.json',sha256:sha(fs.readFileSync(R+'working-identity-registry.json')),bytes:fs.statSync(R+'working-identity-registry.json').size,unchanged:true},scopeArguments:scopes.flatMap(p=>['--scope',p]),D:{fatalFindings:fatal,count:fatal.length,scope:scopes},E:{structuralFatal:fatal,conservationOpen:conservation.open,strictGreen:false,pendingSourceRows:566},stats,preliminaryCandidateUnverified:{native:false,count:reverse.length,units:reverse},duplicateGroups};
